// regionalModeSubsystems is THE manifest of the background units regional mode
// runs, in Serve() start order (COR-832): rate-limit cleanup, the globaldb
// region check, the provisioning reconciler, then the mirror-done /
// perms-backfill / verified-email consumers when NATS built them (NATS is
// required at boot in regional mode, so in practice all three are present),
// the org-invitation token sweep, the detach cleanup relay, and the
// cascade-delete finisher.
//
// The reconciler is unconditional here: regional always wires a full
// JurisdictionCapabilities group (buildJurisdictionCaps in api_server.go), so
// provisioningReconcilerSubsystem's nil-caps guard never trips in practice.
// RunReconciler's own point-of-use check (the unwired-RepoBridge case)
// preserves the warn-and-skip behavior if the bridge is ever unconfigured.
//
// Regional deliberately does NOT run the perms webhook / read-model consumers:
// the GitHub-perms ingress is global-only (regional builds neither consumer).
// The account-erasure poller is started inline in Serve() (it needs the
// fully-wired *api.Server as its region eraser), not via this manifest.
func regionalModeSubsystems(deps serveDeps, srv *coreapi.Server) ([]subsystem, error) {
	var (
		subs []subsystem
		err  error
	)
	if subs, err = requireSubsystem(subs, srv, rateLimitCleanupSubsystem); err != nil {
		return nil, err
	}
	// The check belongs on the GLOBAL pool — the multi-region database with the
	// REGIONAL BY ROW tables — never on this cell's regional pool.
	if subs, err = requireSubsystem(subs, deps.globalPool, globalDBRegionCheckSubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, srv.JurisdictionCaps(), provisioningReconcilerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.mirrorCreateConsumer, mirrorCreateSubsystem); err != nil {
		return nil, err
	}
	for _, c := range deps.mirrorDoneConsumers {
		if subs, err = requireSubsystem(subs, c, mirrorDoneSubsystem); err != nil {
			return nil, err
		}
	}
	if subs, err = maybeSubsystem(subs, deps.nativeMirrorExecutor, nativeMirrorExecutorSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.nativeMirrorCreateConsumer, nativeMirrorCreateSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.nativeMirrorRequestSweep, nativeMirrorRequestSweepSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.entireDataPrimarySink.assignmentPass(), entireDataPrimaryPassSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.trustReconciler, trustReconcilerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.placementAcceptanceWorker, placementAcceptanceSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.trustRootOnCreateSweep, trustRootOnCreateSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.mirrorURLDrainer, mirrorURLDrainerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.repoCellCleanupDrainer, repoCellCleanupDrainerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.permsBackfillConsumer, permsBackfillSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.pluginGrantsConsumer, pluginGrantsSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.verifiedEmailConsumer, verifiedEmailSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.emailRelay, emailRelaySubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.emailConsumer, emailConsumerSubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, deps.orgInvitationTokenSweeper, orgInvitationTokenSweepSubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, srv, detachCleanupRelaySubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, srv, repoDetachSweepSubsystem); err != nil {
		return nil, err
	}
	if subs, err = requireSubsystem(subs, srv, cascadeDeleteFinisherSubsystem); err != nil {
		return nil, err
	}
	return subs, nil
}

// buildRegionalServeDeps assembles the full serving-core dependency graph for a
// regional core: identity/regional/authz/resource stores, the account-erasure
// outbox (drained by a per-region poller, ADR 20260708) and the transactional-
// email fan-out (outbox + relay + consumer), signing keys, JWKS,
// the cluster registry (reconciled here — serving cores own it), and the repo
// bridge. The account-deletion reaper does NOT use this bootstrap: it wires a
// lean control-plane-only graph via buildReaperDeps (ADR 20260707), which is why
// this no longer takes withFanout / reconcileRegistry flags.
func buildRegionalServeDeps(ctx context.Context, cfg Config, lifecycleEmitter *resourceevents.Emitter, billingSubjects []runnerpolicy.BillingSubject) (serveDeps, func(), error) {
	var deps serveDeps

	if cfg.GlobalCockroachDSN == "" {
		return deps, func() {}, errors.New("GLOBAL_COCKROACH_DSN is required in regional mode")
	}
	if cfg.Jurisdiction == "" {
		return deps, func() {}, errors.New("--jurisdiction is required in regional mode")
	}
	if cfg.AuthBaseURL == "" {
		return deps, func() {}, errors.New("ENTIRE_CORE_AUTH_BASE_URL is required in regional mode")
	}
	billingEnforcement, err := runnerpolicy.ParseBillingEnforcement(cfg.RunnerBillingEnforcement)
	if err != nil {
		return deps, func() {}, fmt.Errorf("ENTIRE_RUNNER_BILLING_ENFORCEMENT: %w", err)
	}
	if cfg.RegionHosts == "" {
		return deps, func() {}, errors.New("REGION_HOSTS is required in regional mode")
	}

	// Two pools: global (identity, resources, keys) + regional (PII, audit).
	globalPool, err := postgres.NewPool(ctx, cfg.GlobalCockroachDSN, postgres.WithMaxConns(pgPoolMaxConns))
	if err != nil {
		return deps, func() {}, fmt.Errorf("connect global cockroachdb: %w", err)
	}

	regionalPool, err := postgres.NewPool(ctx, cfg.CockroachDSN, postgres.WithMaxConns(pgPoolMaxConns))
	if err != nil {
		globalPool.Close()
		return deps, func() {}, fmt.Errorf("connect regional cockroachdb: %w", err)
	}
	cleanups := []func(){
		func() { regionalPool.Close() },
		func() { globalPool.Close() },
	}
	cleanup := func() {
		for _, cleanup := range slices.Backward(cleanups) {
			cleanup()
		}
	}

	// Reads go to the local SpiceDB (sidecar/replica); writes go to the
	// read-write authz-writer when configured, else back to the sidecar.
	spiceRead, spiceWrite, err := dialSpiceDB(cfg)
	if err != nil {
		cleanup()
		return deps, func() {}, err
	}
	// Read-mostly: only contacts the authz-writer when the datastore's schema
	// is stale/absent, so a writer/NLB outage doesn't block boot. Never fatal:
	// a fresh cell that can't write its schema serves schema-less (authz-gated
	// requests 500) and the retry converges once the writer is back.
	if !authz.EnsureSchema(ctx, spiceRead, spiceWrite) {
		retryCtx, cancelRetry := context.WithCancel(ctx)
		cleanups = append(cleanups, cancelRetry)
		go authz.EnsureSchemaUntilCurrent(retryCtx, spiceRead, spiceWrite, time.Minute)
	}

	deps.globalPool = globalPool
	deps.identitySvc = membershipIdentityStore(cfg, globalPool)
	deps.authzSvc = authz.NewStoreRW(spiceRead, spiceWrite)

	// System service-account grants are reconciled by `entire-core
	// bootstrap` (see internal/entirecore/bootstrap.go); they require
	// the system org and service_accounts rows that bootstrap creates.
	// Run bootstrap once before the first serve.

	pluginsStore := plugins.NewStore(globalPool)
	pluginCatalog := plugins.NewCatalogStore(globalPool)
	deps.pluginCatalog, deps.pluginAdmin = pluginCatalog, pluginCatalog
	// Held concrete too: the executor needs PublishRepoInTx, not on the interface.
	resourceStore := resource.NewStore(globalPool, deps.authzSvc,
		resource.WithProcessingCellElection(cfg.MirrorElectInProcessingCellEnabled))
	// The detach runs in the placement's jurisdiction, so only a regional
	// core serves it.
	deps.detachStore = repodetach.NewStore(globalPool)
	deps.resourceSvc = resourceStore
	deps.automationSvc = automation.NewStore(globalPool)
	grantProvisioner := plugins.Provisioner{
		Installations: pluginsStore, Plugins: pluginCatalog, Automations: deps.automationSvc, Grants: deps.authzSvc, Fence: resourceStore,
	}
	deps.detachPluginReconciler = plugins.CoveringReconciler{Installations: pluginsStore, Provisioner: grantProvisioner}
	deps.pluginsSvc = pluginsStore
	deps.runnerPolicySvc = newRunnerPolicyStore(globalPool, billingEnforcement, billingSubjects)
	if err := deps.runnerPolicySvc.RegisterModeGauge(); err != nil {
		slogutil.Warn(ctx, "runner policy mode gauge registration failed", slog.String("error", err.Error()))
	}
	billingEnsure := billing.NewGlobalEnsureStore(globalPool)
	billingDir := newRegionalBillingDirectory(ctx, cfg, deps.resourceSvc, deps.identitySvc)
	deps.billingEnsurer = billing.NewEnsurer(billingEnsure, billingDir)
