// globalModeSubsystems is THE manifest of the background units global mode
// runs, in Serve() start order (COR-832): rate-limit cleanup first, the
// globaldb region check, then the perms webhook + read-model consumers when
// NATS built them.
//
// Global deliberately does NOT run:
//   - the provisioning reconciler — global has no regional store to drive, and
//     COR-730 wired resourceSvc into global; the old resourceSvc-only gate
//     started the reconciler here and crashlooped entire-core-global. Its
//     absence from this manifest is now the structural guard (there is no path
//     that can add it), superseding the former data-gate.
//   - mirror-done / perms-backfill consumers — global's mirrorRepoSvc is
//     read-only, so there is no writable placement store for them to reconcile.
//   - the verified-email consumer — verified_emails is home-jurisdiction
//     partitioned data (COR-661/COR-757), owned by regional mode only.
func globalModeSubsystems(deps serveDeps, srv *coreapi.Server) ([]subsystem, error) {
	var (
		subs []subsystem
		err  error
	)
	if subs, err = requireSubsystem(subs, srv, rateLimitCleanupSubsystem); err != nil {
		return nil, err
	}
	// Global mode's single pool IS the global database.
	if subs, err = requireSubsystem(subs, deps.globalPool, globalDBRegionCheckSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.permsWebhookConsumer, permsWebhookSubsystem); err != nil {
		return nil, err
	}
	if subs, err = maybeSubsystem(subs, deps.permsReadModelConsumer, permsReadModelSubsystem); err != nil {
		return nil, err
	}
	return subs, nil
}

func buildGlobalServeDeps(ctx context.Context, cfg Config, lifecycleEmitter *resourceevents.Emitter, billingSubjects []runnerpolicy.BillingSubject) (serveDeps, func(), error) {
	var deps serveDeps
	// Stamp the emitter before any consumer builds read it: Serve assigns
	// deps.lifecycleEmitter only after this builder returns, which left the
	// webhook-perms consumer's repo.renamed gate reading a nil field.
	deps.lifecycleEmitter = lifecycleEmitter

	// Global is a thin router: identity lookup -> redirect to home region.
	// No JWT, no JWKS, no regional. It does now construct a SpiceDB store
	// (COR-730) to light up the mirror-perms event fast-path + COR-758
	// visibility propagation — but that wiring is fail-safe (see below): a
	// broken SpiceDB config degrades those paths without bricking the router.
	if cfg.AuthBaseURL == "" {
		return deps, func() {}, errors.New("ENTIRE_CORE_AUTH_BASE_URL is required in global mode")
	}
	billingEnforcement, err := runnerpolicy.ParseBillingEnforcement(cfg.RunnerBillingEnforcement)
	if err != nil {
		return deps, func() {}, fmt.Errorf("ENTIRE_RUNNER_BILLING_ENFORCEMENT: %w", err)
	}
	if cfg.RegionHosts == "" {
		return deps, func() {}, errors.New("REGION_HOSTS is required in global mode")
	}
	if cfg.HomeRegionCookieSecret == "" {
		return deps, func() {}, errors.New("HOME_REGION_COOKIE_SECRET is required in global mode")
	}

	dsn := cfg.GlobalCockroachDSN
	if dsn == "" {
		dsn = cfg.CockroachDSN
	}
	pool, err := postgres.NewPool(ctx, dsn, postgres.WithMaxConns(pgPoolMaxConns))
	if err != nil {
		return deps, func() {}, fmt.Errorf("connect cockroachdb: %w", err)
	}
	cleanups := []func(){func() { pool.Close() }}
	cleanup := func() {
		// Reverse construction order so the NATS connection drops
		// before the pool it might want to log on teardown.
		for _, cleanup := range slices.Backward(cleanups) {
			cleanup()
		}
	}

	// Global mode's one pool is the global database, so it is also the pool the
	// globaldb region check probes.
	deps.globalPool = pool
	deps.pluginCatalog = plugins.NewCatalogStore(pool)
	deps.runnerPolicySvc = newRunnerPolicyStore(pool, billingEnforcement, billingSubjects)
	if err := deps.runnerPolicySvc.RegisterModeGauge(); err != nil {
		slogutil.Warn(ctx, "runner policy mode gauge registration failed", slog.String("error", err.Error()))
	}
	deps.identitySvc = membershipIdentityStore(cfg, pool)
	deps.oauthStateStore = authn.NewOAuthStateStore(pool)

	// Account-scoped teardown deps. Global owns the global CRDB, where both
	// the federation bindings (external_identity_bindings) and the domain
	// audit log live, so it can erase bindings + write the deletion audit
	// trail directly — the account-deletion reaper reuses this same wiring
	// (buildReaperDeps). Formerly bundled in idpCaps, which global can't
	// build; lifted to top-level deps (ADR 20260707). Plain NewDomainAudit,
	// not WithOutbox: global has no regional pool to fan an audit copy into.
	deps.oidcfedSvc = oidcfed.NewStore(pool)
	deps.domainAudit = audit.NewDomainAudit(pool)

	deps.cookie = authn.NewHomeJurisdictionCookie([]byte(cfg.HomeRegionCookieSecret), cfg.CookieDomain)
	deps.commitTokens = committoken.NewSigner([]byte(cfg.HomeRegionCookieSecret))

	deps.regionHosts = cfg.ParseRegionHosts()
	authHostsRaw := cfg.ParseJurisdictionAuthHosts()
	if err := errOnPartialJurisdictionAuthHosts(authHostsRaw, deps.regionHosts); err != nil {
		return deps, func() {}, err
	}
	deps.jurisdictionAuthHosts = MergeAuthHosts(authHostsRaw, deps.regionHosts)
	// The router validates a known user's home jurisdiction against the auth
	// host map, not the console deep-link map.
	deps.router = authn.NewRouter(authn.RouterConfig{
		Identity:    deps.identitySvc,
		RegionHosts: deps.jurisdictionAuthHosts,
	})
	deps.handoffReturnToHosts = cfg.JurisdictionHandoffReturnToHosts
	deps.loginStartURL = cfg.LoginStartURL
	// ENT-1058: the global bare-root redirect and the jurisdiction-login
	// fallbacks depend on ENTIRE_LOGIN_START_URL. Surface a misconfig loudly at
	// startup so a malformed value is not silently indistinguishable from unset
	// (both otherwise degrade to the landing page / auth error page).
	if cfg.LoginStartURL == "" {
		slogutil.Warn(ctx, "ENTIRE_LOGIN_START_URL unset: global bare-root serves the landing page and jurisdiction-login fallbacks render the auth error page instead of bouncing to the BFF (ENT-1058)")
	} else if u, err := neturl.Parse(cfg.LoginStartURL); err != nil || u.Scheme == "" || u.Host == "" {
		slogutil.Error(ctx, "ENTIRE_LOGIN_START_URL is set but unparseable; treated as unset (no bare-root redirect; login fallbacks render the auth error page)", slog.String("value", cfg.LoginStartURL))
	}

	// Perms webhook consumer. Global owns this; regional has none — the
	// perms layer is global-only. The consumer mirrors only
	// installation/repo metadata (COR-437); user access edges live in
	// SpiceDB.
	deps.githubPerms = githubperms.NewService(pool,
		githubperms.WithRepoGroupNameRefresher(resource.NewStore(pool, nil)),
		githubperms.WithMirrorURLAliasRefresher(mirrorrepo.NewService(pool)),
	)

	// SpiceDB in global (COR-730): light up the event fast-path. With authzSvc
	// + resourceSvc present, buildMirrorPermsReconciler returns non-nil (the
	// read-model consumer's reconcile hook writes grants) and the COR-758
	// visibility adapter un-dorms. Fail-safe by construction — see
	// wireSpiceDBForGlobal: a malformed endpoint degrades to nil services (the
	// reconciler stays dormant) rather than failing boot and taking down the
	// router. Global does NOT own the SpiceDB schema, so no WriteSchema here.
	//
	// Constructed BEFORE mirrorRepoSvc: MarkSuspended needs the grant revoker
	// by value at construction (COR-832 explicit wiring), so resourceSvc must
	// exist first — unlike the consumers below, which read authzSvc/resourceSvc
	// lazily via closures.
	deps.authzSvc, deps.resourceSvc = wireSpiceDBForGlobal(ctx, cfg, pool)

	// mirrorRepoSvc is mostly read-only in global mode — the consumer reads
	// placements to enrich consumer events, and the bootstrap path runs in
	// regional — but global DOES serve the admin suspend route
	// (POST /api/admin/mirrors/{id}/suspend), whose MarkSuspended must revoke
	// grants. WithGrantRevoker wires that, same as regional; when
	// wireSpiceDBForGlobal degraded to nil above, the revoker degrades with it
	// (MarkSuspended nil-guards) rather than failing boot.
	//
	// MUST be assigned before the consumer builds below: buildPermsReadModelConsumer
	// copies deps.mirrorRepoSvc EAGERLY into its permswebhook config (Mirrors),
	// so anything a consumer consumes by value has to exist first. Assigning it
	// after (as an earlier build did) captured a typed nil and nil-panicked on
	// the first membership/team/org event — the COR-730 poison-event incident.
	deps.entireDataPrimarySink = &lazyEntireDataPrimaryReconciler{}
	deps.mirrorRepoSvc = newMirrorRepoService(pool, deps.resourceSvc, deps.entireDataPrimarySink, lifecycleEmitter)
	deps.nativeMirrorSvc = nativemirror.New(pool)

	// COR-523: consume installation/repo metadata straight off
	// webhooks_github_v1. This is the sole metadata path now that the
	// cmd/fanout -> mirror_perms_v1 hop has been removed. Global is also
	// the producer of the repo_ops_v1 teardown jobs, fanned out to the region
	// owning each placement (enumerated via deps.mirrorRepoSvc): every
	// GitHub-side removal — repository.deleted, app uninstall, and repo
	// removed from the install — tears the mirrors down (COR-454).
	webhookConsumer, webhookConsumerCleanup, err := buildPermsWebhookConsumer(ctx, cfg, deps.githubPerms, &deps)
	if err != nil {
		cleanup()
		return deps, func() {}, err
	}
	if webhookConsumerCleanup != nil {
		cleanups = append(cleanups, webhookConsumerCleanup)
	}
	deps.permsWebhookConsumer = webhookConsumer

	// Collaborator-access read-model consumer (member events) backing
	// /mirrors/available. Off unless ENTIRE_GITHUB_PERMS_READ_MODEL_ENABLED +
	// the GitHub App are configured; the reconciler CronJob backfills
	// independently. NOT an authz path (COR-435).
	readModelConsumer, readModelCleanup, err := buildPermsReadModelConsumer(ctx, cfg, &deps)
	if err != nil {
		cleanup()
		return deps, func() {}, err
	}
	if readModelCleanup != nil {
		cleanups = append(cleanups, readModelCleanup)
	}
	deps.permsReadModelConsumer = readModelConsumer

	// No migrations — init containers handle that.

	startRepoGroupBackfill(ctx, pool)

	return deps, cleanup, nil
}

// wireSpiceDBForGlobal constructs the SpiceDB-backed authz + resource stores
// for global mode, fail-safe. Global's primary duty is identity-redirect /
// routing, which must survive a SpiceDB outage, so this never returns an error:
// dialSpiceDBAuthzStore (built on dialSpiceDB) only constructs clients (the
// gRPC dial is lazy — an unreachable but well-formed endpoint surfaces
// per-RPC, counted, not here), so the only failure caught is a malformed
// endpoint/config. That degrades to nil,nil with a WARN, leaving the
// mirror-perms fast-path + COR-758 visibility propagation dormant, rather
// than failing boot.
func wireSpiceDBForGlobal(ctx context.Context, cfg Config, pool *pgxpool.Pool) (authz.Service, resource.Service) {
	authzSvc, err := dialSpiceDBAuthzStore(cfg)
	if err != nil {
		slogutil.Warn(ctx, "global: SpiceDB client construction failed (reader or writer); mirror-perms event fast-path + visibility propagation stay dormant (router unaffected)",
			slog.Any("error", err))
		return nil, nil
	}
	return authzSvc, resource.NewStore(pool, authzSvc, resource.WithProcessingCellElection(cfg.MirrorElectInProcessingCellEnabled))
}

