// billingReturnDomains are the registrable domains a Checkout return URL may use.
var billingReturnDomains = []string{"entire.com", "entire.io", "partial.to"}

func validBillingReturnURL(raw string) bool {
	u, err := url.Parse(raw)
	if err != nil || u.Scheme != "https" || u.User != nil || u.Hostname() == "" {
		return false
	}
	host := strings.ToLower(u.Hostname())
	for _, d := range billingReturnDomains {
		if host == d || strings.HasSuffix(host, "."+d) {
			return true
		}
	}
	return false
}

