			slogutil.Error(ctx, "authz.Can failed", slog.Any("error", err))
			return nil, authzUnavailable()
		}
		if !allowed {
			return nil, forbidden("permission denied")
		}
		if ok, reason := s.Server.CheckOrgSSOForOrg(claims, org); !ok {
			return nil, forbidden(reason)
		}
		loadedOrg = org
	case "account":
		acctID, err := model.ParseAccountID(in.Body.OwnerID)
		if err != nil {
			return nil, badRequest("invalid ownerId")
		}
		if _, err := idSvc.GetAccount(ctx, acctID); err != nil {
			if errors.Is(err, identity.ErrNotFound) {
				return nil, notFound("account not found")
			}
			slogutil.Error(ctx, "GetAccount failed", slog.Any("error", err))
			return nil, internalErr()
		}
		if claims.AccountID.String() != ownerID.String() {
			if !s.ManageAuthority.allowsWrite(ctx) {
				return nil, forbidden("permission denied")
			}
		}
