func (s *ProjectService) GrantProjectAccess(ctx context.Context, in *corev1.GrantProjectAccessInput) (*corev1.GrantProjectAccessOutput, error) {
	claims := api.ClaimsFromContext(ctx)
	if claims == nil {
		return nil, unauthorized("authentication required")
	}
	projectID, err := model.ParseProjectID(in.ProjectID)
	if err != nil {
		return nil, badRequest("invalid project id")
	}
	res := s.Server.Resource()
	authz := s.Server.Authz()
	idSvc := s.Server.Identity()
	if res == nil || authz == nil || idSvc == nil {
		return nil, unavailable("services not configured")
	}
	project, err := res.GetProject(ctx, projectID)
	if err != nil {
		if errors.Is(err, resource.ErrNotFound) {
			return nil, notFound("project not found")
		}
		slogutil.Error(ctx, "GetProject failed", slog.Any("error", err))
		return nil, internalErr()
	}
	if project.OwnerType == "org" {
		orgID, err := model.ParseOrgID(project.OwnerID.String())
		if err != nil {
			// org-owned project with a non-OrgID owner column is a
			// data-integrity failure: fail closed rather than silently
			// bypassing the SSO gate.
			slogutil.Error(ctx, "parse org id", slog.Any("error", err))
			return nil, internalErr()
		}
		if ok, reason, err := s.Server.CheckOrgSSO(ctx, claims, orgID); err != nil {
			slogutil.Error(ctx, "CheckOrgSSO failed", slog.Any("error", err))
			return nil, authzUnavailable()
		} else if !ok {
			return nil, forbidden(reason)
		}
	}
	allowed, err := s.ManageAuthority.gateAllowed(ctx, coreauthz.RetryDeniedFresh, authz, "account:"+claims.AccountID.String(), "manage", "project:"+projectID.String())
	if err != nil {
		slogutil.Error(ctx, "authz.Can failed", slog.Any("error", err))
		return nil, authzUnavailable()
	}
	if !allowed {
		return nil, forbidden("permission denied")
	}
	if err := rejectIfMirrorProject(ctx, s.Server, project, "grant_project_access"); err != nil {
		return nil, err
	}
	granteeType := in.Body.GranteeType
	if granteeType == "" {
		granteeType = "account"
	}
	accountID, err := resolveGrantAccountID(ctx, idSvc, in.Body.AccountID, in.Body.Provider, in.Body.ProviderUserID, false)
	if err != nil {
		return nil, err
	}
	if err := res.GrantProjectAccess(ctx, projectID, granteeType, model.ID(accountID), in.Body.Role); err != nil {
		return nil, mapGrantAccessError(ctx, err, "GrantProjectAccess")
	}
	s.Server.DomainAuditLog(ctx, claims.AccountID, "project_access_granted", "project", projectID.String(), map[string]any{
		"grantee_account_id": accountID.String(),
		"provider":           in.Body.Provider,
		"provider_user_id":   in.Body.ProviderUserID,
		"role":               in.Body.Role,
	})
	s.Server.LifecycleEvents().Publish(ctx, resourceevents.TypeProjectGrant, projectID.String(), resourceevents.OpCreated, claims.AccountID.String())
	out := &corev1.GrantProjectAccessOutput{Status: http.StatusCreated}
	out.Body.Status = "granted"
	return out, nil
}

