package resource

import (
	"cmp"
	"context"
	"errors"
	"fmt"
	"log/slog"
	"slices"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgconn"
	"github.com/jackc/pgx/v5/pgxpool"

	"entire.io/core/authz"
	"entire.io/core/model"
	"entire.io/core/pagination"
	"entire.io/core/plugins"
	"entire.io/core/registry"
	"entire.io/core/resourceevents"
	"entire.io/core/resourceevents/outbox"
	"entire.io/core/staleread"
	"entire.io/postgres"
	"entire.io/slogutil"
)

// pgSerializationFailure is the SQLSTATE that CockroachDB and Postgres
// return when an in-flight transaction loses its serializable race and
// the application must retry from the beginning. CockroachDB's docs
// explicitly require client-side retry on this code; pgx surfaces it
// via *pgconn.PgError.Code.
const pgSerializationFailure = "40001"

// ErrRepoGroupBeingDeleted rejects placement creation after primary deletion
// has claimed the group row. Create and delete serialize on that row so one
// upstream can never be reminted under a second group identity mid-reap.
var ErrRepoGroupBeingDeleted = errors.New("repo group is being deleted")

// ErrNotApplicable is a lookup asked to resolve an identity it cannot address —
// a forge ref that names a repo on an upstream forge rather than a placement
// here. Distinct from a not-found: the row is not missing, the question does
// not apply, and a caller reporting it as missing data would send an operator
// looking for the wrong thing.
var ErrNotApplicable = errors.New("resource: identity is not addressable here")

const defaultHumanOwnedOrgsPerAccount = 3

// DefaultHumanProjectsPerOwner is the per-owner project quota.
const DefaultHumanProjectsPerOwner = 5

// isSerializationFailure reports whether err is a SQLSTATE 40001
// retryable serialization error. Walks the wrapped error chain.
func isSerializationFailure(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == pgSerializationFailure
}

// isUniqueViolation reports whether err is a SQLSTATE 23505 unique-constraint
// violation. Walks the wrapped error chain.
func isUniqueViolation(err error) bool {
	var pgErr *pgconn.PgError
	return errors.As(err, &pgErr) && pgErr.Code == "23505"
}

// membershipsAccountOrgKey is the UNIQUE (account_id, org_id) constraint from
// migration 001. The workos_org_membership_id key is a different conflict.
const membershipsAccountOrgKey = "memberships_account_id_org_id_key"

// isMembershipDuplicate reports whether err is a unique violation of the
// one-membership-per-(account, org) constraint.
func isMembershipDuplicate(err error) bool {
	pgErr, ok := errors.AsType[*pgconn.PgError](err)
	return ok && pgErr.Code == "23505" && pgErr.ConstraintName == membershipsAccountOrgKey
}

// execer is satisfied by both *pgxpool.Pool and pgx.Tx, so
// bumpMembershipsVersion can run inside a transaction (org deletion) or as a
// standalone statement (add/remove member).
type execer interface {
	Exec(ctx context.Context, sql string, args ...any) (pgconn.CommandTag, error)
}

// bumpMembershipsVersion increments the per-account memberships_version
// counter that backs the /orgs ETag. It is the chokepoint every membership
// mutation funnels through, in lieu of a DB trigger. Accounts with no row
// (e.g. a service-account principal, which never carries org memberships) are
// a silent no-op — UPDATE of zero rows is not an error.
func bumpMembershipsVersion(ctx context.Context, db execer, accountIDs ...model.AccountID) error {
	if len(accountIDs) == 0 {
		return nil
	}
	ids := make([]string, len(accountIDs))
	for i, id := range accountIDs {
		ids[i] = id.String()
	}
	if _, err := db.Exec(ctx,
		`UPDATE accounts SET memberships_version = memberships_version + 1 WHERE id = ANY($1)`,
		ids,
	); err != nil {
		return fmt.Errorf("bump memberships_version: %w", err)
	}
	return nil
}

// orgQuotaLimit and projectQuotaLimit are the sole policy hooks for the
// hard-coded initial quotas. Per-owner persisted overrides can replace their
// bodies without changing resource-service or API call signatures.
func (s *Store) orgQuotaLimit(_ context.Context, _ model.AccountID) (int, error) {
	return defaultHumanOwnedOrgsPerAccount, nil
}

func (s *Store) projectQuotaLimit(_ context.Context, _ string, _ model.ID) (int, error) {
	return DefaultHumanProjectsPerOwner, nil
}

// Store implements Service backed by CockroachDB. It takes an
// authz.Service dependency to write SpiceDB relations when
// resources are created or access is modified.
type Store struct {
	pool  *pgxpool.Pool
	authz authz.Service
	// electInProcessingCell limits new primary choices to the project's
	// primary processing cell; see WithProcessingCellElection.
	electInProcessingCell bool
	// followerAOSTPin replaces the AS OF SYSTEM TIME clause spliced into this
	// store's follower reads. Empty in production (and unreachable from outside
	// the package) — tests pin it to a fixed historical timestamp so the
	// stale-read error path is reachable without racing however far
	// follower_read_timestamp() happens to lag. See export_test.go.
	followerAOSTPin postgres.AOST
	// reads selects the follower-read clause; see postgres.FollowerReads. An
	// explicit followerAOSTPin still wins.
	reads postgres.FollowerReads
	// afterReservedNameGrantCheckForTest runs between CreateProject's grant
	// pre-check and the create statement. Nil in production and unreachable
	// from outside the package — it is the only way to close that window
	// deterministically, and the branch it reaches decides whether a caller
	// who lost the grant is told the name is reserved or that it is over
	// quota. See export_test.go.
	afterReservedNameGrantCheckForTest func(context.Context)
}

// followerAOST is the AS OF SYSTEM TIME clause every follower read of this store
// splices in: postgres.FollowerReadAOST unless a test pinned it.
// snapshotAOST reads at the caller's commit timestamp, or from the nearest
// replica when it has none. Neither arm reaches the leaseholder.
//
// Every *Snapshot read below is built on this and shares one contract: the
// caller's own write is in that snapshot by construction, so the answer is
// authoritative and there is no fresh-on-miss or fresh-on-empty retry. That
// retry is exactly what the *FollowerRead counterparts exist to do.
func (s *Store) snapshotAOST(token postgres.CommitToken) postgres.AOST {
	if token == "" {
		return s.followerAOST()
	}
	return postgres.AOSTAt(token)
}

func (s *Store) followerAOST() postgres.AOST {
	if s.followerAOSTPin != "" {
		return s.followerAOSTPin
	}
	return s.reads.AOST()
}

