func NewStore(pool *pgxpool.Pool, authzSvc authz.Service, opts ...Option) *Store {
	s := &Store{pool: pool, authz: authzSvc}
	for _, opt := range opts {
		opt(s)
	}
	return s
}

// Option configures a Store.
type Option func(*Store)

// WithProcessingCellElection limits each new processing-primary choice, each
// admin override, and each new Entire data primary to placements in the owning
// project's primary processing cell
// (ADR 20260909-project-primary-processing-cell). A current primary that is
// still eligible stays, so a group whose primary is in another cell keeps it.
// A project without a cell elects as before.
func WithProcessingCellElection(enabled bool) Option {
	return func(s *Store) { s.electInProcessingCell = enabled }
}

// WithFollowerReadsForTest restores the production follower-read clause
// under NewStoreForTest.
func WithFollowerReadsForTest() Option {
	return func(s *Store) { s.reads = postgres.FollowerReads{} }
}

// NewStoreForTest is NewStore with follower reads served fresh; see
// postgres.FreshFollowerReadsForTest. A test of the follower clause itself
// adds WithFollowerReadsForTest.
func NewStoreForTest(pool *pgxpool.Pool, authzSvc authz.Service, opts ...Option) *Store {
	s := &Store{pool: pool, authz: authzSvc, reads: postgres.FreshFollowerReadsForTest()}
	for _, opt := range opts {
		opt(s)
	}
