// CreateOrg creates a human-owned org. normalizeOrgName trims and validates
// the name to the same shape as a project name, which also rejects any name
// containing ':' — that reserves the ':' namespace for system-managed orgs
// (e.g. "entire:system", "gh:<github-org-id>") so a human can never create an
// org whose name collides with one. It also refuses Entire's own names
// (reservedOrgNames) with ErrReservedName. Trusted callers that need a
// reserved name use CreateOrgWithoutValidation.
func (s *Store) CreateOrg(ctx context.Context, name, region string, ownerAccountID model.AccountID) (OrgCreation, error) {
	name, err := normalizeOrgName(name)
	if err != nil {
		return OrgCreation{}, err
	}
	return s.createOrg(ctx, name, region, ownerAccountID, true)
}

// CreateOrgWithoutValidation creates an org while SKIPPING all name
// validation: the ':' namespace check and the reserved-name check.
//
// DANGER: this is the backdoor that the validated CreateOrg exists to close.
// It is the ONLY way to mint an org in the reserved ':' namespace
// (e.g. serviceaccount.SystemOrgName "entire:system") or with a reserved
// name. Call it ONLY with a name your own code
// constructs — NEVER with a user- or attacker-supplied string, or a human
// can squat a system org name and hijack it.
func (s *Store) CreateOrgWithoutValidation(ctx context.Context, name, region string, ownerAccountID model.AccountID) (*model.Org, error) {
	created, err := s.createOrg(ctx, name, region, ownerAccountID, false)
	return created.Org, err
}

