	SELECT org_creations, org_creation_limit FROM accounts WHERE id = $1
),
ins_org AS (
	INSERT INTO orgs (id, name, region, creation_ordinal)
	SELECT $2, $3, $4, CASE WHEN $8::bool THEN (SELECT org_creations FROM ledger) + 1 END
	FROM owned
	WHERE ($5::bigint IS NULL OR owned.n < $5)
	  AND (NOT $8::bool OR COALESCE((SELECT org_creation_limit IS NULL OR org_creations < org_creation_limit FROM ledger), true))
	RETURNING created_at
