ins_membership AS (
	INSERT INTO memberships (id, account_id, org_id, role, zed_token, zed_token_at, activated_at)
	SELECT $6, $1, $2, 'owner', NULLIF($7, ''), CASE WHEN $7 <> '' THEN now() END, now()
	FROM ins_org
	RETURNING 1
),
bump AS (
	UPDATE accounts SET
		memberships_version = memberships_version + 1,
		org_creations = org_creations + CASE WHEN $8::bool THEN 1 ELSE 0 END
	WHERE id = $1 AND EXISTS (SELECT 1 FROM ins_org)
	RETURNING 1
)
SELECT (SELECT created_at FROM ins_org), (SELECT n FROM owned),
       (SELECT org_creations FROM ledger), (SELECT org_creation_limit FROM ledger)`

func (s *Store) createOrg(ctx context.Context, name, region string, ownerAccountID model.AccountID, enforceQuota bool) (OrgCreation, error) {
	org := &model.Org{
		ID:     model.NewOrgID(),
		Name:   name,
		Region: region,
	}

	var limit *int64
	if enforceQuota {
		l, err := s.orgQuotaLimit(ctx, ownerAccountID)
		if err != nil {
			return OrgCreation{}, fmt.Errorf("resolve organization quota: %w", err)
		}
		lim := int64(l)
		limit = &lim
	}

	rev, err := s.authz.OrgCreated(ctx, org.ID, ownerAccountID)
	if err != nil {
		wrapped := fmt.Errorf("authz org created: %w", err)
		s.rollbackOrgCreationAuthz(ctx, org.ID, wrapped)
		return OrgCreation{}, wrapped
	}

	ownerMembershipID := model.NewMembershipID()

	var (
		manageAllowed bool
		checkErr      error
		createdAt     *time.Time
		ownedCount    int64
		created       *int64
		creationLimit *int64
		sqlErr        error
		wg            sync.WaitGroup
	)
	wg.Add(2)
	go func() {
		defer wg.Done()
		manageAllowed, checkErr = s.authz.CanAtLeastAsFresh(ctx, rev, "account:"+ownerAccountID.String(), "manage", "org:"+org.ID.String())
	}()
	go func() {
		defer wg.Done()
		sqlErr = s.pool.QueryRow(ctx, createOrgSQL,
			ownerAccountID, org.ID, org.Name, org.Region, limit, ownerMembershipID, rev.Token(), enforceQuota,
		).Scan(&createdAt, &ownedCount, &created, &creationLimit)
	}()
	wg.Wait()

	if sqlErr != nil {
		// Only a ':' name can collide.
		if isUniqueViolation(sqlErr) {
			wrapped := fmt.Errorf("org name %q: %w", org.Name, ErrNameConflict)
			s.rollbackOrgCreationAuthz(ctx, org.ID, wrapped)
			return OrgCreation{}, wrapped
		}
		wrapped := fmt.Errorf("create org: %w", sqlErr)
		existingCreatedAt, exists, existsErr := s.orgRow(ctx, org.ID)
		switch resolveAmbiguousCommit(exists, existsErr) {
		case commitAmbiguitySucceeded:
			org.CreatedAt = existingCreatedAt
			if checkErr != nil {
				return OrgCreation{Org: org, Revision: rev}, s.logUnresolvableCapabilityCheck(ctx, org.ID, checkErr)
			}
			return OrgCreation{Org: org, Revision: rev, ManageAllowed: manageAllowed}, nil
		case commitAmbiguityFailed:
			s.rollbackOrgCreationAuthz(ctx, org.ID, wrapped)
		case commitAmbiguityUnresolved:
			slogutil.Error(ctx, "create org failure could not be resolved - SpiceDB tuples left in place",
				slog.String("org_id", org.ID.String()),
				slog.Any("check_err", existsErr),
				slog.Any("cause", wrapped))
		}
		return OrgCreation{}, wrapped
	}

	if createdAt == nil {
		wrapped := fmt.Errorf("account %s owns %d organizations: %w", ownerAccountID, ownedCount, ErrOrgQuotaExceeded)
		if enforceQuota && created != nil && creationLimit != nil && *created >= *creationLimit {
			wrapped = fmt.Errorf("account %s created %d of %d organizations: %w", ownerAccountID, *created, *creationLimit, ErrOrgCreationLimit)
		}
		s.rollbackOrgCreationAuthz(ctx, org.ID, wrapped)
		return OrgCreation{}, wrapped
	}
	org.CreatedAt = *createdAt
	if enforceQuota && created != nil {
		org.CreationOrdinal = *created + 1
	}

	if checkErr != nil {
		return OrgCreation{Org: org, Revision: rev}, s.logUnresolvableCapabilityCheck(ctx, org.ID, checkErr)
	}

	return OrgCreation{Org: org, Revision: rev, ManageAllowed: manageAllowed}, nil
}

func (s *Store) logUnresolvableCapabilityCheck(ctx context.Context, orgID model.OrgID, checkErr error) error {
	wrapped := fmt.Errorf("resolve owner capabilities: %w", checkErr)
	slogutil.Error(ctx, "capability check failed after org creation committed - org and its SpiceDB grants stand",
		slog.String("org_id", orgID.String()),
		slog.Any("cause", wrapped))
	return wrapped
}

func (s *Store) orgRow(ctx context.Context, id model.OrgID) (createdAt time.Time, exists bool, err error) {
	checkCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 5*time.Second)
