// renames and can't be reused across owners — the projects_name_key
// collision/leak hazard the COR-432 "key on the id, never the login" rule
// exists to prevent.
func MirrorsProjectName(ownerID model.ID) string {
	return MirrorsProjectNamePrefix + ownerID.String()
}

