func (s *Store) GrantProjectAccess(ctx context.Context, projectID model.ProjectID, granteeType string, granteeID model.ID, role string) error {
	if granteeType != "account" {
		return fmt.Errorf("%q: %w", granteeType, ErrUnsupportedGranteeType)
	}
	if !validGrantRoles[role] {
		return fmt.Errorf("%q: %w", role, ErrInvalidRole)
	}
	_, err := s.pool.Exec(ctx,
		`INSERT INTO project_permissions (project_id, grantee_type, grantee_id, role)
		 VALUES ($1, $2, $3, $4)
		 ON CONFLICT (project_id, grantee_type, grantee_id)
		 DO UPDATE SET role = EXCLUDED.role`,
		projectID, granteeType, granteeID, role,
	)
	if err != nil {
		return fmt.Errorf("upsert project permission: %w", err)
	}

	if err := s.authz.ProjectPermissionGranted(ctx, projectID, granteeType, granteeID, role); err != nil {
		return fmt.Errorf("authz project permission: %w", err)
	}

	return nil
}

// ListProjectAccess returns one keyset page of a project's grants, ordered by
// the (grantee_type, grantee_id) pair that's unique within a project.
// nextCursor is empty on the last page.
//
//nolint:dupl // parallel to ListRepoAccess but queries a different table for a different typed ID; a generic helper would obscure the query.
func (s *Store) ListProjectAccess(ctx context.Context, projectID model.ProjectID, limit int, cursor string) ([]ProjectMember, string, error) {
	limit = pagination.ClampLimit(limit)
	keys, err := pagination.DecodeCursor(cursor, 2)
	if err != nil {
		return nil, "", fmt.Errorf("decode cursor: %w", err)
	}
	where := "project_id = $1"
	args := []any{projectID}
	if keys != nil {
		where += fmt.Sprintf(" AND (grantee_type, grantee_id) > ($%d, $%d)", len(args)+1, len(args)+2)
		args = append(args, keys[0], keys[1])
	}
	args = append(args, limit+1)
	rows, err := s.pool.Query(ctx, fmt.Sprintf(
		`SELECT grantee_type, grantee_id, role
		 FROM project_permissions WHERE %s
		 ORDER BY grantee_type, grantee_id LIMIT $%d`, where, len(args)), args...,
	)
	if err != nil {
		return nil, "", fmt.Errorf("list project members: %w", err)
	}
	defer rows.Close()
	out := []ProjectMember{}
	for rows.Next() {
		var m ProjectMember
		if err := rows.Scan(&m.GranteeType, &m.GranteeID, &m.Role); err != nil {
			return nil, "", fmt.Errorf("scan project member: %w", err)
		}
		out = append(out, m)
	}
	if err := rows.Err(); err != nil {
		return nil, "", fmt.Errorf("iterate project members: %w", err)
	}
	next := ""
	if len(out) > limit {
		out = out[:limit]
		last := out[len(out)-1]
		next = pagination.EncodeCursor(last.GranteeType, last.GranteeID)
	}
	return out, next, nil
}

func (s *Store) RevokeProjectAccess(ctx context.Context, projectID model.ProjectID, granteeType string, granteeID model.ID) error {
	var role string
	err := s.pool.QueryRow(ctx,
		`DELETE FROM project_permissions
		 WHERE project_id = $1 AND grantee_type = $2 AND grantee_id = $3
		 RETURNING role`,
		projectID, granteeType, granteeID,
	).Scan(&role)
	if err != nil {
		if errors.Is(err, pgx.ErrNoRows) {
			return fmt.Errorf("project permission: %w", ErrNotFound)
		}
