func (s *Store) deleteOrg(ctx context.Context, id model.OrgID, allowLinked bool) error {
	// Retry on SQLSTATE 40001: under serializable isolation, any
	// concurrent transaction that touches an overlapping row can force
	// CockroachDB to abort this one with a retryable error. The whole
	// transactional body must run again from begin to commit — pgx will
	// not let us reuse the aborted handle.
	const maxAttempts = 5
	backoff := 5 * time.Millisecond
	var memberAccounts []model.AccountID
	var lastErr error
	for attempt := range maxAttempts {
		accounts, err := s.deleteOrgTx(ctx, id, allowLinked)
		if err == nil {
			memberAccounts = accounts
			lastErr = nil
			break
		}
		if !isSerializationFailure(err) {
			return err
		}
		lastErr = err
		slogutil.Warn(ctx, "DeleteOrg retrying on serialization failure",
			slog.String("org_id", id.String()),
			slog.Int("attempt", attempt+1),
			slog.Any("error", err))
		select {
		case <-ctx.Done():
			return fmt.Errorf("delete org: %w", ctx.Err())
		case <-time.After(backoff):
		}
		backoff *= 2
	}
	if lastErr != nil {
		return fmt.Errorf("delete org after %d attempts: %w", maxAttempts, lastErr)
	}

	// Best-effort authz cleanup after the DB is settled. If this fails,
	// the DB is already consistent; the orphaned SpiceDB tuples point to
	// a non-existent org.
	for _, acct := range memberAccounts {
		if _, err := s.authz.MembershipRevoked(ctx, acct, id); err != nil {
			return fmt.Errorf("authz membership revoked for %s (DB delete already committed): %w", acct, err)
		}
	}
	// Also clears billing_admin and the platform anchor.
	if err := s.authz.OrgDeleted(ctx, id); err != nil {
		return fmt.Errorf("authz org deleted (DB delete already committed): %w", err)
	}
	return nil
}

// deleteOrgTx runs the DeleteOrg transactional body once. Returns the
// list of memberships whose authz tuples need post-commit revocation.
// Pulled out so DeleteOrg can retry on SQLSTATE 40001 without
// duplicating the rollback / commit dance.
func (s *Store) deleteOrgTx(ctx context.Context, id model.OrgID, allowLinked bool) ([]model.AccountID, error) {
	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("begin tx: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // safe to ignore if commit succeeded

	// Refuse to delete an org that still owns projects, and do it INSIDE this
	// transaction. Paired with the project-create statements' owner read: a
	// project insert that lands before this commit is seen by this count
	// (refuse, ErrHasDependents); one that lands after sees the org gone
	// (ErrOwnerGone). A plain pre-check outside the tx would see neither.
	// Matches the ErrHasDependents surfaced by the teams FK.
	var projectCount int
	var linked bool
	if err := tx.QueryRow(ctx,
		`SELECT (SELECT count(*) FROM projects WHERE owner_type = 'org' AND owner_id = $1), `+orgIsGitHubLinkedSQL, id,
	).Scan(&projectCount, &linked); err != nil {
		return nil, fmt.Errorf("count owned projects: %w", err)
	}
	if projectCount > 0 {
		return nil, fmt.Errorf("org %s: %w", id, ErrHasDependents)
	}
	if linked && !allowLinked {
		return nil, fmt.Errorf("org %s: %w", id, ErrLinkedOrg)
	}

	// Capture memberships we're about to delete so we can revoke their
	// authz tuples after commit.
	rows, err := tx.Query(ctx,
		`SELECT account_id FROM memberships WHERE org_id = $1`, id,
	)
	if err != nil {
		return nil, fmt.Errorf("list memberships: %w", err)
	}
	var memberAccounts []model.AccountID
	for rows.Next() {
		var acct model.AccountID
		if err := rows.Scan(&acct); err != nil {
			rows.Close()
			return nil, fmt.Errorf("scan membership: %w", err)
		}
		memberAccounts = append(memberAccounts, acct)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate memberships: %w", err)
	}

	if _, err := tx.Exec(ctx, `DELETE FROM memberships WHERE org_id = $1`, id); err != nil {
		return nil, fmt.Errorf("delete memberships: %w", err)
	}

	// Cascading the member rows away changes each member's org list, so bump
	// their membership versions in the same transaction.
	if err := bumpMembershipsVersion(ctx, tx, memberAccounts...); err != nil {
		return nil, err
	}

	tag, err := tx.Exec(ctx, `DELETE FROM orgs WHERE id = $1`, id)
	if err != nil {
		// A dependent (teams.org_id) still references the org. Surface it as
		// a typed conflict so the handler can 409 rather than 500.
		var pgErr *pgconn.PgError
		if errors.As(err, &pgErr) && pgErr.Code == "23503" {
			return nil, fmt.Errorf("org %s: %w", id, ErrHasDependents)
		}
		return nil, fmt.Errorf("delete org: %w", err)
	}
	if tag.RowsAffected() == 0 {
		return nil, fmt.Errorf("org %s: %w", id, ErrNotFound)
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("commit tx: %w", err)
	}
	return memberAccounts, nil
}

