func (s *Store) GrantRepoAccess(ctx context.Context, repoID model.RepoID, granteeType string, granteeID model.ID, role string) error {
	if err := validateRepoGrant(granteeType, role); err != nil {
		return err
	}

	// Resolve the group BEFORE writing anything: a github-forge or
	// native-mirror placement (!dualWrite) must be a true no-op — writing
	// then unconditionally deleting the repo_permissions row would clobber a
	// historical row for this grantee, hiding it from ListRepoAccess and making
	// RevokeRepoAccess 404 even though SpiceDB access persists.
	groupID, dualWrite, detachIncomplete, err := s.repoGroupForDualWriteWithDetach(ctx, repoID, true)
	if err != nil {
		if errors.Is(err, ErrNotFound) {
			// repoGroupForDualWriteWithDetach's ErrNotFound means no repo_registry row
			// joins to a repo_group at all — the same "not published yet"
			// state RecordRepoAccess's FK used to catch first, back when it
			// ran before this resolution. Surface the same retryable error.
			return fmt.Errorf("repo %s: %w", repoID, ErrRepoNotReady)
		}
		return err
	}
	if !dualWrite {
		// A github-forge group gets its grants only from mirrorperms. A
		// native-mirror placement holds no grant of its own. Touch neither
		// store.
		return nil
	}
	if detachIncomplete {
		return fmt.Errorf("repo %s: %w", repoID, ErrDetachInProgress)
	}
	// SpiceDB first: it is the authz gate (the truth). GroupOnlyRoleGranted
	// clears any stale placement-level role (RepoCreated still seeds the
	// creator's role directly onto the placement) and writes the group grant
	// in one SpiceDB write, re-asserting the structural repo#group edge
	// along the way — a failed creation-time link self-heals here too. A
	// failure here returns before the projection is touched at all, so a
	// failed downgrade can never mask itself as having landed.
	if err := s.authz.GroupOnlyRoleGranted(ctx, repoID, groupID, granteeType, granteeID, role); err != nil {
		return fmt.Errorf("authz group permission: %w", err)
	}
	if err := s.RecordRepoAccess(ctx, repoID, granteeType, granteeID, role); err != nil {
		return err
	}
	return nil
}

// repoGroupForDualWrite resolves repoID's repo_group and reports whether a
// grant/revoke chokepoint should touch it, closing two gaps a bare
// ResolveRepoGroupIDByPlacement lookup left open:
//
//   - Sole-writer safety: a "github"-forge group's reader/writer/
//     mirror_source_admin relations are exclusively source-managed
//     (core/mirrorperms's package doc; manual grants on those relations are
