// Package outbox is the durable, payload-carrying outbox for repo resource
// events that need at-least-once delivery.
//
// A core-NATS publish is at-most-once (COR-616). A producer enqueues the fully
// marshaled event in its own transaction, and one relay per jurisdiction
// publishes the stored bytes through JetStream. The relay deletes a row only
// after a positive PubAck. A stream outage delays an event and never loses it.
//
// Rows are keyed by (repo_id, op). Each op has its own conflict rule in
// conflictRules: a detach keeps the first row, a rename keeps the latest. A
// new producer adds its op there or EnqueueInTx refuses it.
//
// Drain model: per-replica polling with FOR UPDATE SKIP LOCKED, the
// core/nativemirror CreatedOutboxRelay shape. Regional entire-core scales
// horizontally, so concurrent relays must claim disjoint batches. The publish
// and the post-ack DELETE run inside the claiming transaction, because the
// claim's lock ends with that transaction. A commit failure after the ack
// leaves the row, and the republish carries the same Nats-Msg-Id.
//
// Delivery is at least once. The stream's msg-id window absorbs a republish
// inside it, and the consumer must absorb one outside it.
package outbox

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"sort"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
	"go.opentelemetry.io/otel"
	"go.opentelemetry.io/otel/attribute"

	"entire.io/core/observability"
	"entire.io/core/resourceevents"
	"entire.io/slogutil"
)

// Table keeps the name of its first producer. The metrics do too.
const Table = "repo_detached_outbox"

const (
	relayInterval = 15 * time.Second
	relayBatch    = 100
	// relayCommitGrace bounds the post-publish DELETE and commit on a detached
	// context. A shutdown mid-drain must not roll back cleanup for events that
	// the stream already acknowledged.
	relayCommitGrace = 5 * time.Second
)

// conflictRules is the one place a repeated enqueue is resolved.
var conflictRules = map[string]string{
	// Creation keeps its original timestamp and default eligibility on retry.
	resourceevents.OpCreated: `ON CONFLICT (repo_id, op) DO NOTHING`,
	// A resumed detach repeats its enqueue; the first payload stands.
	resourceevents.OpDetached: `ON CONFLICT (repo_id, op) DO NOTHING`,
	// Two renames before a drain publish the newest name once.
	resourceevents.OpRenamed: `ON CONFLICT (repo_id, op) DO UPDATE SET
		 subject = EXCLUDED.subject, msg_id = EXCLUDED.msg_id, payload = EXCLUDED.payload,
		 jurisdiction = EXCLUDED.jurisdiction, created_at = EXCLUDED.created_at`,
}

// Ops lists the ops the outbox accepts, in a fixed order.
func Ops() []string {
	ops := make([]string, 0, len(conflictRules))
	for op := range conflictRules {
		ops = append(ops, op)
	}
	sort.Strings(ops)
	return ops
}

// Row is one queued event. Every field is required.
type Row struct {
	// RepoID is the placement the event is about.
	RepoID string
	// Op is the resourceevents op. It picks the conflict rule.
	Op string
	// Jurisdiction routes the row to that jurisdiction's relay.
	Jurisdiction string
	// Subject and Payload are published verbatim.
	Subject string
	Payload []byte
	// MsgID is the stream's deduplication key.
	MsgID string
}

func (r Row) validate() error {
	var missing []string
	if r.RepoID == "" {
		missing = append(missing, "repo id")
	}
	if r.Op == "" {
		missing = append(missing, "op")
	}
	if r.Jurisdiction == "" {
		missing = append(missing, "jurisdiction")
	}
	if r.Subject == "" {
		missing = append(missing, "subject")
	}
	if len(r.Payload) == 0 {
		missing = append(missing, "payload")
	}
	if r.MsgID == "" {
		missing = append(missing, "msg id")
	}
	if len(missing) > 0 {
		return fmt.Errorf("outbox: row is missing %v", missing)
	}
	return nil
}

// ConflictClause returns op's conflict rule for a producer that writes the
// row inside its own SQL statement. It panics on an op without a rule.
func ConflictClause(op string) string {
	conflict, ok := conflictRules[op]
	if !ok {
		panic(fmt.Sprintf("outbox: no conflict rule for op %q", op))
	}
	return conflict
}

// EnqueueInTx records row in the caller's transaction on the global database,
// so the event is queued if and only if that transaction commits. A second
// row for the same (repo_id, op) resolves by the op's conflict rule. An op
// without a rule is an error.
func EnqueueInTx(ctx context.Context, tx pgx.Tx, row Row) error {
	if err := row.validate(); err != nil {
		return err
	}
	conflict, ok := conflictRules[row.Op]
	if !ok {
		return fmt.Errorf("outbox: no conflict rule for op %q", row.Op)
	}
	if _, err := tx.Exec(ctx,
		`INSERT INTO `+Table+` (repo_id, op, subject, msg_id, payload, jurisdiction)
		 VALUES ($1, $2, $3, $4, $5, $6) `+conflict,
		row.RepoID, row.Op, row.Subject, row.MsgID, row.Payload, row.Jurisdiction,
	); err != nil {
		return fmt.Errorf("outbox: enqueue %s for %s: %w", row.Op, row.RepoID, err)
	}
	return nil
}

// Publisher is the acknowledged raw-publish surface the relay needs.
// *resourceevents.Emitter satisfies it.
type Publisher interface {
	PublishAckMsg(ctx context.Context, msgID, subject string, payload []byte) error
}

// Option configures a Relay.
type Option func(*Relay)

// WithSampler adds a gauge sample to every relay pass. Coverage advances
// only when every sample succeeds.
func WithSampler(sample func(context.Context) error) Option {
	return func(r *Relay) { r.samplers = append(r.samplers, sample) }
}

// NewRelay binds a relay to the global pool and to the jurisdiction whose
// rows it drains. A nil or disabled publisher keeps every row queued, and the
// backlog metrics expose the gap.
func NewRelay(pool *pgxpool.Pool, jurisdiction string, publisher Publisher, opts ...Option) *Relay {
	r := &Relay{pool: pool, jurisdiction: jurisdiction, publisher: publisher, interval: relayInterval, batch: relayBatch}
	for _, opt := range opts {
		opt(r)
	}
	return r
}

// Relay drains one jurisdiction's pending events, every op in created_at
// order.
type Relay struct {
	pool         *pgxpool.Pool
	jurisdiction string
	publisher    Publisher
	interval     time.Duration
	batch        int
	coverage     *observability.Coverage
	samplers     []func(context.Context) error
}

// Run drains immediately, then again on each interval until ctx ends.
func (r *Relay) Run(ctx context.Context) {
	if r == nil || r.pool == nil {
		return
	}
	r.coverage = observability.NewCoverage(otel.Meter(meterName), "entirecore.repo_detached_outbox.observation_age_seconds", attribute.String("jurisdiction", r.jurisdiction))
	defer r.coverage.Close()
	r.drainAndRecord(ctx)
	ticker := time.NewTicker(r.interval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
			r.drainAndRecord(ctx)
		}
	}
}

func (r *Relay) drainAndRecord(ctx context.Context) {
	if _, err := r.DrainOnce(ctx); err != nil {
		recordDrainFailure(ctx, r.jurisdiction)
		slogutil.Warn(ctx, "resource-event outbox drain failed",
			slog.String("jurisdiction", r.jurisdiction),
			slog.String("error", err.Error()))
	}
	sampled := true
	if err := r.RecordBacklog(ctx); err != nil {
		sampled = false
		slogutil.Warn(ctx, "resource-event outbox backlog sample failed",
			slog.String("jurisdiction", r.jurisdiction),
			slog.String("error", err.Error()))
	}
	for _, sample := range r.samplers {
		if err := sample(ctx); err != nil {
			sampled = false
			slogutil.Warn(ctx, "resource-event outbox sample failed",
				slog.String("jurisdiction", r.jurisdiction),
				slog.String("error", err.Error()))
		}
	}
	// A failed sample leaves its gauges at the last value, so coverage
	// advances only when every sample succeeds.
	if sampled {
		r.coverage.Success()
	}
}

type pendingEvent struct {
	repoID  string
	op      string
	subject string
	msgID   string
	payload []byte
}

// DrainOnce claims up to one batch of this jurisdiction's rows and publishes
// each with an acknowledged JetStream publish. It returns the number of rows
// acknowledged and removed. A failed publish keeps its row for a later pass
// and does not stop the rest of the batch, so one rejected payload cannot
// block the backlog.
func (r *Relay) DrainOnce(ctx context.Context) (int, error) {
	if r == nil || r.pool == nil {
		return 0, errors.New("outbox: relay is not configured")
	}
	tx, err := r.pool.Begin(ctx)
	if err != nil {
		return 0, fmt.Errorf("begin resource-event outbox drain: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // no-op after commit

	rows, err := tx.Query(ctx,
		`SELECT repo_id, op, subject, msg_id, payload
		 FROM `+Table+`
		 WHERE jurisdiction = $1
		 ORDER BY created_at, repo_id, op
		 LIMIT $2
		 FOR UPDATE SKIP LOCKED`,
		r.jurisdiction, r.batch)
	if err != nil {
		return 0, fmt.Errorf("select resource-event outbox batch: %w", err)
	}
	var batch []pendingEvent
	for rows.Next() {
		var p pendingEvent
		if err := rows.Scan(&p.repoID, &p.op, &p.subject, &p.msgID, &p.payload); err != nil {
			rows.Close()
			return 0, fmt.Errorf("scan resource-event outbox row: %w", err)
		}
		batch = append(batch, p)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return 0, fmt.Errorf("iterate resource-event outbox rows: %w", err)
	}
	rows.Close()
	if len(batch) == 0 {
		return 0, nil
	}

	var (
		ackedRepoIDs []string
		ackedOps     []string
		errs         []error
	)
	for _, p := range batch {
		if r.publisher == nil {
			errs = append(errs, resourceevents.ErrAcknowledgedPublishingDisabled)
			break
		}
		if err := r.publisher.PublishAckMsg(ctx, p.msgID, p.subject, p.payload); err != nil {
			recordPublishFailure(ctx, r.jurisdiction, p.op)
			errs = append(errs, fmt.Errorf("publish repo.%s for %s: %w", p.op, p.repoID, err))
			continue
		}
		ackedRepoIDs = append(ackedRepoIDs, p.repoID)
		ackedOps = append(ackedOps, p.op)
	}
	if len(ackedRepoIDs) == 0 {
		return 0, errors.Join(errs...)
	}

	commitCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), relayCommitGrace)
	defer cancel()
	if _, err := tx.Exec(commitCtx,
		`DELETE FROM `+Table+`
		 WHERE (repo_id, op) IN (SELECT r, o FROM unnest($1::TEXT[], $2::TEXT[]) AS u(r, o))`,
		ackedRepoIDs, ackedOps); err != nil {
		return 0, errors.Join(append(errs, fmt.Errorf("delete acknowledged resource-event rows: %w", err))...)
	}
	if err := tx.Commit(commitCtx); err != nil {
		return 0, errors.Join(append(errs, fmt.Errorf("commit resource-event outbox drain: %w", err))...)
	}
	for _, op := range ackedOps {
		recordPublished(ctx, r.jurisdiction, op)
	}
	return len(ackedRepoIDs), errors.Join(errs...)
}

// RecordBacklog samples this jurisdiction's pending rows and the age of the
// oldest, per op. An op without rows records zero, so an alert on the age
// resolves after a drain.
func (r *Relay) RecordBacklog(ctx context.Context) error {
	if r == nil || r.pool == nil {
		return errors.New("outbox: relay is not configured")
	}
	ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
	defer cancel()
	rows, err := r.pool.Query(ctx,
		`SELECT op, count(*),
		        COALESCE(EXTRACT(EPOCH FROM (now() - min(created_at)))::INT8, 0)
		 FROM `+Table+`
		 WHERE jurisdiction = $1
		 GROUP BY op`,
		r.jurisdiction)
	if err != nil {
		return fmt.Errorf("sample resource-event outbox: %w", err)
	}
	defer rows.Close()
	type backlog struct{ count, oldestAge int64 }
	byOp := make(map[string]backlog, len(conflictRules))
	for rows.Next() {
		var (
			op string
			b  backlog
		)
		if err := rows.Scan(&op, &b.count, &b.oldestAge); err != nil {
			return fmt.Errorf("scan resource-event outbox sample: %w", err)
		}
		byOp[op] = b
	}
	if err := rows.Err(); err != nil {
		return fmt.Errorf("iterate resource-event outbox sample: %w", err)
	}
	for _, op := range Ops() {
		b := byOp[op]
		recordBacklog(ctx, r.jurisdiction, op, b.count, b.oldestAge)
		delete(byOp, op)
	}
	// A row whose op lost its rule still counts, so it cannot hide.
	for op, b := range byOp {
		recordBacklog(ctx, r.jurisdiction, op, b.count, b.oldestAge)
	}
	return nil
}

package audit

import (
	"context"
	"errors"
	"fmt"
	"log/slog"
	"time"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"

	"entire.io/slogutil"
)

// outboxTable is the regional table staging un-drained domain audit events.
const outboxTable = "domain_audit_outbox"

const (
	// defaultRelayInterval is how often the relay drains the outbox. It bounds
	// how long the global audit read paths (GET /api/admin/audit) trail a
	// write: one tick + one cross-region batch insert, a few seconds worst
	// case.
	defaultRelayInterval = 1 * time.Second
	// defaultRelayBatch is rows per regional transaction / global batch
	// insert. DrainOnce loops batch after batch, so this caps lock hold and
	// per-round-trip payload, not throughput.
	defaultRelayBatch = 256

	// commitGracePeriod bounds the detached delete+commit after a successful
	// global insert, so a shutdown mid-drain banks progress instead of
	// re-shipping the batch (harmless, but wasteful) — while a wedged DB
	// can't pin the goroutine past shutdown.
	commitGracePeriod = 5 * time.Second

	backlogSampleInterval = 30 * time.Second
)

// Relay drains staged audit events from the regional outbox into the global
// domain_audit_events table and deletes the drained rows. Delivery is
// at-least-once: a crash between the global insert and the outbox delete
// redelivers the row, and the global insert is ON CONFLICT (id) DO NOTHING, so
// redelivery is invisible. Concurrent relays (other pods in the region) claim
// disjoint rows via FOR UPDATE SKIP LOCKED.
type Relay struct {
	regional *pgxpool.Pool
	global   *pgxpool.Pool
	interval time.Duration
	batch    int
}

// NewRelay builds a Relay over the regional (outbox) and global
// (domain_audit_events) pools.
func NewRelay(regional, global *pgxpool.Pool) *Relay {
	return &Relay{regional: regional, global: global, interval: defaultRelayInterval, batch: defaultRelayBatch}
}

// Run drains the outbox on an interval and samples the backlog gauges until
// ctx is cancelled. Drain failures are logged and counted, never fatal: rows
// stay queued and the next tick retries, so audit events are lost only if the
// regional table itself is lost.
func (r *Relay) Run(ctx context.Context) {
	drain := time.NewTicker(r.interval)
	defer drain.Stop()
	backlog := time.NewTicker(backlogSampleInterval)
	defer backlog.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-drain.C:
			if err := r.DrainOnce(ctx); err != nil && !errors.Is(err, context.Canceled) {
				recordDrainFailure(ctx)
				slogutil.Warn(ctx, "domain-audit outbox drain failed", slog.String("error", err.Error()))
			}
		case <-backlog.C:
			r.recordBacklog(ctx)
		}
	}
}

// DrainOnce moves staged rows to the global table, batch after batch, until
// the outbox is empty (as seen by this relay — rows locked by a concurrent
// relay are skipped) or an error stops it.
func (r *Relay) DrainOnce(ctx context.Context) error {
	for {
		n, err := r.drainBatch(ctx)
		if err != nil || n < r.batch {
			return err
		}
	}
}

// drainBatch claims one batch of outbox rows, inserts them into the global
// table in a single pipelined round trip, then deletes them. The regional
// transaction holds the claim across the global insert: on any failure it
// rolls back and the rows retry next tick; after a successful insert the
// delete+commit run on a detached context (see commitGracePeriod).
func (r *Relay) drainBatch(ctx context.Context) (int, error) {
	tx, err := r.regional.Begin(ctx)
	if err != nil {
		return 0, fmt.Errorf("begin: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // safe once committed

	rows, err := tx.Query(ctx,
		`SELECT id, actor_account_id, event_type, resource_type, resource_id, metadata, created_at
		 FROM `+outboxTable+` ORDER BY id LIMIT $1 FOR UPDATE SKIP LOCKED`, r.batch)
	if err != nil {
		return 0, fmt.Errorf("select outbox batch: %w", err)
	}
	type staged struct {
		id, actor, eventType, resourceType, resourceID string
		metadata                                       []byte
		createdAt                                      time.Time
	}
	var batch []staged
	for rows.Next() {
		var s staged
		if err := rows.Scan(&s.id, &s.actor, &s.eventType, &s.resourceType, &s.resourceID, &s.metadata, &s.createdAt); err != nil {
			rows.Close()
			return 0, fmt.Errorf("scan outbox row: %w", err)
		}
		batch = append(batch, s)
	}
	if err := rows.Err(); err != nil {
		rows.Close()
		return 0, fmt.Errorf("iterate outbox rows: %w", err)
	}
	rows.Close()
	if len(batch) == 0 {
		return 0, nil
	}

	// One pipelined round trip to global. created_at is the request-time
	// value carried from the outbox, not drain time. ON CONFLICT absorbs
	// redelivery after a crash between insert and delete.
	insert := &pgx.Batch{}
	ids := make([]string, 0, len(batch))
	for _, s := range batch {
		insert.Queue(
			`INSERT INTO domain_audit_events (id, actor_account_id, event_type, resource_type, resource_id, metadata, created_at)
			 VALUES ($1, $2, $3, $4, $5, $6, $7) ON CONFLICT (id) DO NOTHING`,
			s.id, s.actor, s.eventType, s.resourceType, s.resourceID, s.metadata, s.createdAt)
		ids = append(ids, s.id)
	}
	if err := r.global.SendBatch(ctx, insert).Close(); err != nil {
		return 0, fmt.Errorf("insert audit events into global: %w", err)
	}

	commitCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), commitGracePeriod)
	defer cancel()
	if _, err := tx.Exec(commitCtx, `DELETE FROM `+outboxTable+` WHERE id = ANY($1)`, ids); err != nil {
		return 0, fmt.Errorf("delete drained outbox rows: %w", err)
	}
	if err := tx.Commit(commitCtx); err != nil {
		return 0, fmt.Errorf("commit outbox drain: %w", err)
	}
	recordRowsDrained(ctx, len(batch))
	return len(batch), nil
}

// recordBacklog samples outbox depth and oldest-row age. A sustained non-zero
// age means the relay is hung or global is unreachable — audit events are
// staged but not visible to the global read paths.
func (r *Relay) recordBacklog(ctx context.Context) {
	var pending int64
	var oldestAge float64
	err := r.regional.QueryRow(ctx,
		`SELECT count(*), COALESCE(EXTRACT(EPOCH FROM now() - min(created_at)), 0) FROM `+outboxTable).
		Scan(&pending, &oldestAge)
	if err != nil {
		slogutil.Warn(ctx, "domain-audit outbox backlog sample failed", slog.String("error", err.Error()))
		return
	}
	recordBacklogSample(ctx, pending, int64(oldestAge))
}

