1	// Package outbox is the durable, payload-carrying outbox for repo resource
2	// events that need at-least-once delivery.
3	//
4	// A core-NATS publish is at-most-once (COR-616). A producer enqueues the fully
5	// marshaled event in its own transaction, and one relay per jurisdiction
6	// publishes the stored bytes through JetStream. The relay deletes a row only
7	// after a positive PubAck. A stream outage delays an event and never loses it.
8	//
9	// Rows are keyed by (repo_id, op). Each op has its own conflict rule in
10	// conflictRules: a detach keeps the first row, a rename keeps the latest. A
11	// new producer adds its op there or EnqueueInTx refuses it.
12	//
13	// Drain model: per-replica polling with FOR UPDATE SKIP LOCKED, the
14	// core/nativemirror CreatedOutboxRelay shape. Regional entire-core scales
15	// horizontally, so concurrent relays must claim disjoint batches. The publish
16	// and the post-ack DELETE run inside the claiming transaction, because the
17	// claim's lock ends with that transaction. A commit failure after the ack
18	// leaves the row, and the republish carries the same Nats-Msg-Id.
19	//
20	// Delivery is at least once. The stream's msg-id window absorbs a republish
21	// inside it, and the consumer must absorb one outside it.
22	package outbox
23	
24	import (
25		"context"
26		"errors"
27		"fmt"
28		"log/slog"
29		"sort"
30		"time"
31	
32		"github.com/jackc/pgx/v5"
33		"github.com/jackc/pgx/v5/pgxpool"
34		"go.opentelemetry.io/otel"
35		"go.opentelemetry.io/otel/attribute"
36	
37		"entire.io/core/observability"
38		"entire.io/core/resourceevents"
39		"entire.io/slogutil"
40	)
41	
42	// Table keeps the name of its first producer. The metrics do too.
43	const Table = "repo_detached_outbox"
44	
45	const (
46		relayInterval = 15 * time.Second
47		relayBatch    = 100
48		// relayCommitGrace bounds the post-publish DELETE and commit on a detached
49		// context. A shutdown mid-drain must not roll back cleanup for events that
50		// the stream already acknowledged.
51		relayCommitGrace = 5 * time.Second
52	)
53	
54	// conflictRules is the one place a repeated enqueue is resolved.
55	var conflictRules = map[string]string{
56		// Creation keeps its original timestamp and default eligibility on retry.
57		resourceevents.OpCreated: `ON CONFLICT (repo_id, op) DO NOTHING`,
58		// A resumed detach repeats its enqueue; the first payload stands.
59		resourceevents.OpDetached: `ON CONFLICT (repo_id, op) DO NOTHING`,
60		// Two renames before a drain publish the newest name once.
61		resourceevents.OpRenamed: `ON CONFLICT (repo_id, op) DO UPDATE SET
62			 subject = EXCLUDED.subject, msg_id = EXCLUDED.msg_id, payload = EXCLUDED.payload,
63			 jurisdiction = EXCLUDED.jurisdiction, created_at = EXCLUDED.created_at`,
64	}
65	
66	// Ops lists the ops the outbox accepts, in a fixed order.
67	func Ops() []string {
68		ops := make([]string, 0, len(conflictRules))
69		for op := range conflictRules {
70			ops = append(ops, op)
71		}
72		sort.Strings(ops)
73		return ops
74	}
75	
76	// Row is one queued event. Every field is required.
77	type Row struct {
78		// RepoID is the placement the event is about.
79		RepoID string
80		// Op is the resourceevents op. It picks the conflict rule.
81		Op string
82		// Jurisdiction routes the row to that jurisdiction's relay.
83		Jurisdiction string
84		// Subject and Payload are published verbatim.
85		Subject string
86		Payload []byte
87		// MsgID is the stream's deduplication key.
88		MsgID string
89	}
90	
91	func (r Row) validate() error {
92		var missing []string
93		if r.RepoID == "" {
94			missing = append(missing, "repo id")
95		}
96		if r.Op == "" {
97			missing = append(missing, "op")
98		}
99		if r.Jurisdiction == "" {
100			missing = append(missing, "jurisdiction")
101		}
102		if r.Subject == "" {
103			missing = append(missing, "subject")
104		}
105		if len(r.Payload) == 0 {
106			missing = append(missing, "payload")
107		}
108		if r.MsgID == "" {
109			missing = append(missing, "msg id")
110		}
111		if len(missing) > 0 {
112			return fmt.Errorf("outbox: row is missing %v", missing)
113		}
114		return nil
115	}
116	
117	// ConflictClause returns op's conflict rule for a producer that writes the
118	// row inside its own SQL statement. It panics on an op without a rule.
119	func ConflictClause(op string) string {
120		conflict, ok := conflictRules[op]
121		if !ok {
122			panic(fmt.Sprintf("outbox: no conflict rule for op %q", op))
123		}
124		return conflict
125	}
126	
127	// EnqueueInTx records row in the caller's transaction on the global database,
128	// so the event is queued if and only if that transaction commits. A second
129	// row for the same (repo_id, op) resolves by the op's conflict rule. An op
130	// without a rule is an error.
131	func EnqueueInTx(ctx context.Context, tx pgx.Tx, row Row) error {
132		if err := row.validate(); err != nil {
133			return err
134		}
135		conflict, ok := conflictRules[row.Op]
136		if !ok {
137			return fmt.Errorf("outbox: no conflict rule for op %q", row.Op)
138		}
139		if _, err := tx.Exec(ctx,
140			`INSERT INTO `+Table+` (repo_id, op, subject, msg_id, payload, jurisdiction)
141			 VALUES ($1, $2, $3, $4, $5, $6) `+conflict,
142			row.RepoID, row.Op, row.Subject, row.MsgID, row.Payload, row.Jurisdiction,
143		); err != nil {
144			return fmt.Errorf("outbox: enqueue %s for %s: %w", row.Op, row.RepoID, err)
145		}
146		return nil
147	}
148	
149	// Publisher is the acknowledged raw-publish surface the relay needs.
150	// *resourceevents.Emitter satisfies it.
151	type Publisher interface {
152		PublishAckMsg(ctx context.Context, msgID, subject string, payload []byte) error
153	}
154	
155	// Option configures a Relay.
156	type Option func(*Relay)
157	
158	// WithSampler adds a gauge sample to every relay pass. Coverage advances
159	// only when every sample succeeds.
160	func WithSampler(sample func(context.Context) error) Option {
161		return func(r *Relay) { r.samplers = append(r.samplers, sample) }
162	}
163	
164	// NewRelay binds a relay to the global pool and to the jurisdiction whose
165	// rows it drains. A nil or disabled publisher keeps every row queued, and the
166	// backlog metrics expose the gap.
167	func NewRelay(pool *pgxpool.Pool, jurisdiction string, publisher Publisher, opts ...Option) *Relay {
168		r := &Relay{pool: pool, jurisdiction: jurisdiction, publisher: publisher, interval: relayInterval, batch: relayBatch}
169		for _, opt := range opts {
170			opt(r)
171		}
172		return r
173	}
174	
175	// Relay drains one jurisdiction's pending events, every op in created_at
176	// order.
177	type Relay struct {
178		pool         *pgxpool.Pool
179		jurisdiction string
180		publisher    Publisher
181		interval     time.Duration
182		batch        int
183		coverage     *observability.Coverage
184		samplers     []func(context.Context) error
185	}
186	
187	// Run drains immediately, then again on each interval until ctx ends.
188	func (r *Relay) Run(ctx context.Context) {
189		if r == nil || r.pool == nil {
190			return
191		}
192		r.coverage = observability.NewCoverage(otel.Meter(meterName), "entirecore.repo_detached_outbox.observation_age_seconds", attribute.String("jurisdiction", r.jurisdiction))
193		defer r.coverage.Close()
194		r.drainAndRecord(ctx)
195		ticker := time.NewTicker(r.interval)
196		defer ticker.Stop()
197		for {
198			select {
199			case <-ctx.Done():
200				return
201			case <-ticker.C:
202				r.drainAndRecord(ctx)
203			}
204		}
205	}
206	
207	func (r *Relay) drainAndRecord(ctx context.Context) {
208		if _, err := r.DrainOnce(ctx); err != nil {
209			recordDrainFailure(ctx, r.jurisdiction)
210			slogutil.Warn(ctx, "resource-event outbox drain failed",
211				slog.String("jurisdiction", r.jurisdiction),
212				slog.String("error", err.Error()))
213		}
214		sampled := true
215		if err := r.RecordBacklog(ctx); err != nil {
216			sampled = false
217			slogutil.Warn(ctx, "resource-event outbox backlog sample failed",
218				slog.String("jurisdiction", r.jurisdiction),
219				slog.String("error", err.Error()))
220		}
221		for _, sample := range r.samplers {
222			if err := sample(ctx); err != nil {
223				sampled = false
224				slogutil.Warn(ctx, "resource-event outbox sample failed",
225					slog.String("jurisdiction", r.jurisdiction),
226					slog.String("error", err.Error()))
227			}
228		}
229		// A failed sample leaves its gauges at the last value, so coverage
230		// advances only when every sample succeeds.
231		if sampled {
232			r.coverage.Success()
233		}
234	}
235	
236	type pendingEvent struct {
237		repoID  string
238		op      string
239		subject string
240		msgID   string
241		payload []byte
242	}
243	
244	// DrainOnce claims up to one batch of this jurisdiction's rows and publishes
245	// each with an acknowledged JetStream publish. It returns the number of rows
246	// acknowledged and removed. A failed publish keeps its row for a later pass
247	// and does not stop the rest of the batch, so one rejected payload cannot
248	// block the backlog.
249	func (r *Relay) DrainOnce(ctx context.Context) (int, error) {
250		if r == nil || r.pool == nil {
251			return 0, errors.New("outbox: relay is not configured")
252		}
253		tx, err := r.pool.Begin(ctx)
254		if err != nil {
255			return 0, fmt.Errorf("begin resource-event outbox drain: %w", err)
256		}
257		defer tx.Rollback(ctx) //nolint:errcheck // no-op after commit
258	
259		rows, err := tx.Query(ctx,
260			`SELECT repo_id, op, subject, msg_id, payload
261			 FROM `+Table+`
262			 WHERE jurisdiction = $1
263			 ORDER BY created_at, repo_id, op
264			 LIMIT $2
265			 FOR UPDATE SKIP LOCKED`,
266			r.jurisdiction, r.batch)
267		if err != nil {
268			return 0, fmt.Errorf("select resource-event outbox batch: %w", err)
269		}
270		var batch []pendingEvent
271		for rows.Next() {
272			var p pendingEvent
273			if err := rows.Scan(&p.repoID, &p.op, &p.subject, &p.msgID, &p.payload); err != nil {
274				rows.Close()
275				return 0, fmt.Errorf("scan resource-event outbox row: %w", err)
276			}
277			batch = append(batch, p)
278		}
279		if err := rows.Err(); err != nil {
280			rows.Close()
281			return 0, fmt.Errorf("iterate resource-event outbox rows: %w", err)
282		}
283		rows.Close()
284		if len(batch) == 0 {
285			return 0, nil
286		}
287	
288		var (
289			ackedRepoIDs []string
290			ackedOps     []string
291			errs         []error
292		)
293		for _, p := range batch {
294			if r.publisher == nil {
295				errs = append(errs, resourceevents.ErrAcknowledgedPublishingDisabled)
296				break
297			}
298			if err := r.publisher.PublishAckMsg(ctx, p.msgID, p.subject, p.payload); err != nil {
299				recordPublishFailure(ctx, r.jurisdiction, p.op)
300				errs = append(errs, fmt.Errorf("publish repo.%s for %s: %w", p.op, p.repoID, err))
301				continue
302			}
303			ackedRepoIDs = append(ackedRepoIDs, p.repoID)
304			ackedOps = append(ackedOps, p.op)
305		}
306		if len(ackedRepoIDs) == 0 {
307			return 0, errors.Join(errs...)
308		}
309	
310		commitCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), relayCommitGrace)
311		defer cancel()
312		if _, err := tx.Exec(commitCtx,
313			`DELETE FROM `+Table+`
314			 WHERE (repo_id, op) IN (SELECT r, o FROM unnest($1::TEXT[], $2::TEXT[]) AS u(r, o))`,
315			ackedRepoIDs, ackedOps); err != nil {
316			return 0, errors.Join(append(errs, fmt.Errorf("delete acknowledged resource-event rows: %w", err))...)
317		}
318		if err := tx.Commit(commitCtx); err != nil {
319			return 0, errors.Join(append(errs, fmt.Errorf("commit resource-event outbox drain: %w", err))...)
320		}
321		for _, op := range ackedOps {
322			recordPublished(ctx, r.jurisdiction, op)
323		}
324		return len(ackedRepoIDs), errors.Join(errs...)
325	}
326	
327	// RecordBacklog samples this jurisdiction's pending rows and the age of the
328	// oldest, per op. An op without rows records zero, so an alert on the age
329	// resolves after a drain.
330	func (r *Relay) RecordBacklog(ctx context.Context) error {
331		if r == nil || r.pool == nil {
332			return errors.New("outbox: relay is not configured")
333		}
334		ctx, cancel := context.WithTimeout(ctx, 5*time.Second)
335		defer cancel()
336		rows, err := r.pool.Query(ctx,
337			`SELECT op, count(*),
338			        COALESCE(EXTRACT(EPOCH FROM (now() - min(created_at)))::INT8, 0)
339			 FROM `+Table+`
340			 WHERE jurisdiction = $1
341			 GROUP BY op`,
342			r.jurisdiction)
343		if err != nil {
344			return fmt.Errorf("sample resource-event outbox: %w", err)
345		}
346		defer rows.Close()
347		type backlog struct{ count, oldestAge int64 }
348		byOp := make(map[string]backlog, len(conflictRules))
349		for rows.Next() {
350			var (
351				op string
352				b  backlog
353			)
354			if err := rows.Scan(&op, &b.count, &b.oldestAge); err != nil {
355				return fmt.Errorf("scan resource-event outbox sample: %w", err)
356			}
357			byOp[op] = b
358		}
359		if err := rows.Err(); err != nil {
360			return fmt.Errorf("iterate resource-event outbox sample: %w", err)
361		}
362		for _, op := range Ops() {
363			b := byOp[op]
364			recordBacklog(ctx, r.jurisdiction, op, b.count, b.oldestAge)
365			delete(byOp, op)
366		}
367		// A row whose op lost its rule still counts, so it cannot hide.
368		for op, b := range byOp {
369			recordBacklog(ctx, r.jurisdiction, op, b.count, b.oldestAge)
370		}
371		return nil
372	}
