// a repo. Lifecycle and operational metadata live in core/regional — this
// package exposes only the registry-level reads and the publish/unpublish
// writes the jurisdictional store calls via the regional.Registry interface.

// PublishRepo inserts or refreshes a registry row for a repo, referencing a
// group the caller has already resolved via GetOrCreateRepoGroup. Called by
// the regional store when a repo row is inserted (including 'provisioning'
// reservations — COR-856) and re-asserted on activation. Idempotent:
// re-publishing the same (id, project, name, jurisdiction, cluster_slug)
// succeeds silently so reconciler retries are safe. ClusterSlug is empty for
// pre-rollout rows — those are filled in by the backfill, not by this path.
//
// The caller resolves the group first; this transaction only locks it
// against the reaper (lockRepoGroupForCreateByID, willPlace=true — the
// registry INSERT below attaches a placement, so any pre-existing emptiness
// clock must clear) and inserts the registry row.
//
// Returns the repo_group_id so the caller can hand it to the data plane
// without a second resolve.
func (s *Store) PublishRepo(ctx context.Context, r model.RepoRegistration) (string, error) {
	const maxAttempts = 5
	backoff := 10 * time.Millisecond
	var lastErr error
	for attempt := range maxAttempts {
		groupID, err := s.publishRepoTx(ctx, r)
		if err == nil {
			return groupID, nil
		}
		if !isSerializationFailure(err) {
			return groupID, err
		}
		lastErr = err
		if attempt == maxAttempts-1 {
			break
		}
		select {
		case <-ctx.Done():
			return "", fmt.Errorf("publish repo: %w", ctx.Err())
		case <-time.After(backoff):
		}
		backoff *= 2
	}
	return "", fmt.Errorf("publish repo after %d attempts: %w", maxAttempts, lastErr)
}

func (s *Store) publishRepoTx(ctx context.Context, r model.RepoRegistration) (string, error) {
	tx, err := s.pool.BeginTx(ctx, pgx.TxOptions{})
	if err != nil {
		return "", fmt.Errorf("publish repo: begin: %w", err)
	}
	defer tx.Rollback(ctx) //nolint:errcheck // rollback after commit is a no-op

	groupID, err := s.PublishRepoInTx(ctx, tx, r)
	if err != nil {
		return "", err
	}
	if err := tx.Commit(ctx); err != nil {
		return "", fmt.Errorf("publish repo: commit: %w", err)
	}
	return groupID, nil
}

// PublishRepoInTx is publishRepoTx's body without the transaction, for a caller
// that must not publish unless its own write commits (COR-1698). Never commits.
func (s *Store) PublishRepoInTx(ctx context.Context, tx pgx.Tx, r model.RepoRegistration) (string, error) {
	// willPlace=true: the registry INSERT below attaches this repo's placement
	// to the group in the same transaction, so any pre-existing emptiness clock
	// must clear now. This is also where the group's forge is read (for
	// validateForgeProjectKind) — one lock, one row read, not two.
	forge, err := lockRepoGroupForCreateByID(ctx, tx, r.RepoGroupID, true)
	if err != nil {
		return "", fmt.Errorf("publish repo: %w", err)
	}
	if err := validateForgeProjectKind(ctx, tx, forge, r.OwningProjectID); err != nil {
		return "", err
	}
	// A group with no owning project adopts the one it is being placed into.
	// Attaching a placement is exactly when a group gains an owner, so this is
	// the symmetric counterpart of UnpublishRepo releasing the project when the
	// last placement goes: without it, a group emptied between its mint and this
	// publish would end up with a live placement and a NULL owner, invisible to
	// every project-scoped lookup and listing. mintRepoGroupTx cannot cover that
	// window — it runs in an earlier transaction, and its guard correctly
	// declines to re-stamp a group whose project still held a placement at the
	// time it ran.
	//
	// IS NULL only, so this never overrides an existing owner: first-owner-wins
	// (COR-1041) still governs, and a github group with placements spread across
	// per-cluster fragment projects keeps naming the one it already had. Runs
	// after the forge/project-kind check so a rejected pairing is never stamped,
	// and under the FOR UPDATE the lock above took, so it serializes against a
	// concurrent unpublish releasing the same row.
