	// the project already holds a different group with this group's full_name.
	// That index is only permissive while the pointer is NULL, so releasing a
	// project on unpublish is what lets two same-named groups coexist unowned —
	// and re-publishing one of them into a project holding the other is exactly
	// when they collide. Translated to the same sentinel mintRepoGroupTx and the
	// placement INSERT below already return, so callers keep matching one error
	// rather than a raw unique violation from whichever statement got there
	// first.
	adopted, err := tx.Exec(ctx,
		`UPDATE repo_group SET owning_project_id = $2 WHERE id = $1 AND owning_project_id IS NULL`,
		r.RepoGroupID, r.OwningProjectID,
	)
